const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const cards = () => [...document.querySelectorAll('article[aria-label$="agent"]')];
await wait(4500);
const done = cards().map((el) => ({
  status: el.querySelector('header span:last-child')?.textContent.trim(),
  hypothesis: el.querySelector('p')?.textContent.slice(0, 50),
  chips: [...el.querySelectorAll('dd span.rounded-md')].map((s) => s.textContent),
  phases: [...el.querySelectorAll('ol li')].map((li) => li.textContent.trim() + ':' + (li.querySelector('[aria-label]')?.getAttribute('aria-label') ?? '')),
  h: Math.round(el.getBoundingClientRect().height),
}));
const stage = document.querySelector('header')?.textContent;
const link = (t) => [...document.querySelectorAll('a,button')].find((b) => b.textContent.trim() === t);
link('DRKG embedding')?.click();
await wait(400);
const onEmbedding = location.pathname;
link('Profile agents')?.click();
await wait(300);
const revisit = cards().map((el) => getComputedStyle(el).animationName + '/' + (el.querySelector('header svg')?.getAttribute('class')?.includes('animate-in') ?? false));
({ done, onEmbedding, back: location.pathname, revisit })

